cd /tmp; python3 - <<'EOF'
import struct
data = open('/workspace/artifacts/target/busybox','rb').read()
text_off = 0x3690; text_addr = 0x3690; text_size = 0xbc07
text = data[text_off:text_off+text_size]

targets = {
    'location': 0x10e26,
    'content-length': 0x10e05,
    'transfer-encoding': 0x10e14,
    'http': 0x10e30,
}

# scan for both lea (48 8d / 4c 8d, modrm rip) and mov reg, imm64 (= 48 c7 / 48 b8) referencing these
for name, addr in targets.items():
    refs = []
    for i in range(len(text)-7):
        b = text[i]
        if b in (0x48,0x4c) and text[i+1]==0x8d:
            modrm = text[i+2]
            if (modrm & 0xc7)==0x05:
                disp = struct.unpack_from('<i', text, i+3)[0]
                t = text_addr+i+7+disp
                if t==addr: refs.append(('lea', text_addr+i))
        # movabs rXX, imm64: 48 b8..bf / 49 b8..bf
        if b in (0x48,0x49) and text[i+1] in (0xb8,0xb9,0xba,0xbb,0xbc,0xbd,0xbe,0xbf):
            imm = struct.unpack_from('<Q', text, i+2)[0]
            if imm==addr: refs.append(('movabs', text_addr+i))
    print(f"{name:20s} {[ (k, hex(v)) for k,v in refs ]}")
EOF

